const base = require('./base');

// The configurations spread from another module, assigned in, and written after.
const plugin = {
  rules: {},
  configs: { ...base.configs },
};

Object.assign(plugin.configs, {
  forms: { globals: { superagent: 'readonly' } },
});

plugin.configs.browser = { globals: { ky: 'readonly' } };

module.exports = plugin;
